// Maven pom.xml snippet
<dependencies>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-web</artifactId>
        <!-- No version tag needed - inherited from spring-boot-starter-parent -->
    </dependency>
</dependencies>

// This single starter brings in:
// - spring-webmvc (for @RestController, @RequestMapping)
// - spring-boot-starter-json (Jackson for JSON serialization)
// - spring-boot-starter-tomcat (embedded Tomcat server)
// - spring-boot-starter (core Spring Boot, logging, auto-config)
// - Dozens of transitive dependencies, all at compatible versions

// Gradle build.gradle equivalent
dependencies {
    implementation 'org.springframework.boot:spring-boot-starter-web'
    // Same effect - all transitive dependencies resolved automatically
}

// Integration test - loads full Spring context
@SpringBootTest
class OrderServiceIntegrationTest {

    @Autowired
    private OrderService orderService; // Real bean from context

    @Autowired
    private OrderRepository orderRepository; // Real repository

    @Test
    void shouldCreateOrderWithRealDatabase() {
        var order = orderService.createOrder("Laptop", 1);
        assertThat(order.getId()).isNotNull(); // AssertJ fluent assertion
    }
}

// Unit test - no Spring context, faster execution
class OrderServiceUnitTest {

    @Mock
    private OrderRepository orderRepository; // Mocked with Mockito

    @InjectMocks
    private OrderService orderService; // Class under test

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    void shouldCallRepositorySave() {
        when(orderRepository.save(any())).thenReturn(new Order(1L, "Item"));
        var order = orderService.createOrder("Item", 1);
        verify(orderRepository).save(any()); // Verify mock interaction
        assertThat(order.getId()).isEqualTo(1L);
    }
}

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.web.bind.annotation.*;

record CreateUserRequest(
    @NotNull(message = "Name cannot be null")
    @Size(min = 2, max = 50, message = "Name must be 2-50 characters")
    String name,

    @Email(message = "Invalid email format")
    String email,

    @Min(value = 18, message = "Must be at least 18 years old")
    Integer age
) {}

@RestController
@RequestMapping("/api/users")
class UserController {

    @PostMapping
    public String createUser(@Valid @RequestBody CreateUserRequest request) {
        // Validation happens before this line — if validation fails, method doesn't execute
        return "User created: " + request.name();
    }
}

// If validation fails, Spring returns 400 with JSON:
// {"timestamp":"...","status":400,"errors":["Name cannot be null","Must be at least 18 years old"]}
